import React, { useState } from 'react';
import './Perfil_user.css';
import NavMenu from '../../navMenu/NavMenu';
import { FaUser, FaEnvelope, FaMobileAlt, FaLock, FaImage, FaEdit } from 'react-icons/fa'; // Importa los iconos de Font Awesome u otra librería de iconos

const PerfilUser = () => {
  const [isEditing, setIsEditing] = useState(false);
  const [userData, setUserData] = useState({
    nombre: 'John',
    apellido: 'Doe',
    celular: '123456789',
    email: 'john.doe@example.com',
    pass: '********', // Esto debería manejarse de manera segura
    url: 'https://example.com/profile-image.jpg',
  });

  const handleEdit = () => {
    setIsEditing(!isEditing);
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setUserData({ ...userData, [name]: value });
  };

  return (
    <>
      <NavMenu className="nav-menu" />
      <div className='body-user-perfil'>
        <div className='form-perfil'>
          <h2>PERFIL USUARIO</h2>
          <div className="input-group">
            <div className="input-container">
              <span className="input-icon"><FaUser /></span>
              <input
                type='text'
                name='nombre'
                value={userData.nombre}
                onChange={handleChange}
                placeholder='Nombre'
                disabled={!isEditing}
              />
            </div>
            <div className="input-container">
              <span className="input-icon"><FaEnvelope /></span>
              <input
                type='email'
                name='email'
                value={userData.email}
                onChange={handleChange}
                placeholder='Correo'
                disabled={!isEditing}
              />
            </div>
            <div className="input-container">
              <span className="input-icon"><FaMobileAlt /></span>
              <input
                type='tel'
                name='celular'
                value={userData.celular}
                onChange={handleChange}
                placeholder='Celular'
                disabled={!isEditing}
              />
            </div>
            <div className="input-container">
              <span className="input-icon"><FaLock /></span>
              <input
                type='password'
                name='pass'
                value={userData.pass}
                onChange={handleChange}
                placeholder='Contraseña'
                disabled={!isEditing}
              />
            </div>
            <div className="input-container">
              <span className="input-icon"><FaImage /></span>
              <input
                type='url'
                name='url'
                value={userData.url}
                onChange={handleChange}
                placeholder='URL de la imagen'
                disabled={!isEditing}
              />
            </div>
          </div>
          <div className="btn-editar" onClick={handleEdit}>
            {isEditing ? 'Guardar' : 'Editar'}
            <span className="edit-icon"><FaEdit /></span>
          </div>
        </div>
      </div>
    </>
  );
};

export default PerfilUser;
